import { createClient } from 'npm:@supabase/supabase-js@2'

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, apikey, content-type',
  'Content-Type': 'application/json',
}

function response(body: object, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: cors })
}

function defaultKey(name: string) {
  const values = JSON.parse(Deno.env.get(name) ?? '{}')
  return values.default ?? ''
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors })
  if (req.method !== 'POST') return response({ error: '只接受 POST 請求' }, 405)

  const authorization = req.headers.get('Authorization')
  if (!authorization?.startsWith('Bearer ')) return response({ error: '請先登入' }, 401)

  const url = Deno.env.get('SUPABASE_URL') ?? ''
  const publishableKey = defaultKey('SUPABASE_PUBLISHABLE_KEYS') || Deno.env.get('SUPABASE_ANON_KEY') || ''
  const secretKey = defaultKey('SUPABASE_SECRET_KEYS') || Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') || ''
  const userClient = createClient(url, publishableKey, { global: { headers: { Authorization: authorization } } })
  const token = authorization.slice('Bearer '.length)
  const { data: { user }, error: userError } = await userClient.auth.getUser(token)
  if (userError || !user) return response({ error: '登入已失效，請重新登入' }, 401)

  const { data: profile } = await userClient.from('profiles').select('role, active').eq('id', user.id).maybeSingle()
  if (!profile?.active || profile.role !== 'admin') return response({ error: '僅管理員可管理帳號' }, 403)

  const admin = createClient(url, secretKey, { auth: { autoRefreshToken: false, persistSession: false } })
  const body = await req.json().catch(() => null)
  if (!body || typeof body.action !== 'string') return response({ error: '請提供操作內容' }, 400)

  if (body.action === 'invite') {
    const email = typeof body.email === 'string' ? body.email.trim() : ''
    const displayName = typeof body.displayName === 'string' ? body.displayName.trim() : ''
    if (!/^\S+@\S+\.\S+$/.test(email)) return response({ error: 'Email 格式不正確' }, 400)
    const { data, error } = await admin.auth.admin.inviteUserByEmail(email, { data: { display_name: displayName } })
    if (error) return response({ error: error.message }, 400)
    return response({ userId: data.user.id })
  }

  if (body.action === 'deactivate') {
    const userId = typeof body.userId === 'string' ? body.userId : ''
    if (!/^[0-9a-f-]{36}$/i.test(userId) || userId === user.id) return response({ error: '無法停用此帳號' }, 400)
    const { error } = await admin.from('profiles').update({ active: false }).eq('id', userId)
    if (error) return response({ error: error.message }, 400)
    await admin.auth.admin.signOut(userId, 'global')
    return response({ ok: true })
  }

  return response({ error: '不支援的帳號操作' }, 400)
})
